const axios = require('axios');
const rtFeed = require('./event').rtFeed;

/**
 * Option Chain Manager
 * Fetches ATM strike, generates CE/PE symbols, subscribes via WebSocket,
 * and maintains a live option chain merging tick, bidask, and greeks data.
 */
class OptionChain {
	constructor(symbol, expiry, chainLength, atm, strikeStep, bidAsk, greek) {
		this.symbol = symbol;
		this.expiry = expiry;
		this.chainLength = chainLength;
		this.atm = atm;
		this.strikeStep = strikeStep;
		this.bidAsk = bidAsk;
		this.greek = greek;
		this.optionSymbols = [];
		this.chain = {}; // { symbolName: { tick: {}, greeks: {} } }
		this._listeners = {};

		this._generateSymbols();
	}

	/**
	 * Generate CE and PE symbol names based on ATM, strikeStep, and chainLength.
	 * Symbol format: "[SymbolName][YYMMDD][Strike][CE/PE]"
	 */
	_generateSymbols() {
		const expiryStr = this.expiry;
		const expiryShort = expiryStr.slice(2);

		const strikes = [];
		const halfLength = Math.floor(this.chainLength / 2);

		for (let i = -halfLength; i < this.chainLength - halfLength; i++) {
			strikes.push(this.atm + i * this.strikeStep);
		}

		this.strikes = strikes;
		this.optionSymbols = [];

		strikes.forEach((strike) => {
			const ceSymbol = `${this.symbol}${expiryShort}${strike}CE`;
			const peSymbol = `${this.symbol}${expiryShort}${strike}PE`;
			this.optionSymbols.push(ceSymbol);
			this.optionSymbols.push(peSymbol);

			this.chain[ceSymbol] = { strike, type: 'CE', tick: null, greeks: null };
			this.chain[peSymbol] = { strike, type: 'PE', tick: null, greeks: null };
		});
	}

	/**
	 * Start listening for tick and greeks events and update the chain.
	 * Bidask data comes from tick itself (not a separate event).
	 */
	startListening() {
		// Tick listener — always active
		this._listeners.tick = (tickData) => {
			const sym = tickData.Symbol;
			if (this.chain[sym]) {
				this.chain[sym].tick = tickData;
				this._emitChainUpdate(sym);
			}
		};
		rtFeed.on('tick', this._listeners.tick);

		// Greeks listener — only if enabled
		if (this.greek) {
			this._listeners.greeks = (greeksData) => {
				const sym = greeksData.Symbol;
				if (this.chain[sym]) {
					this.chain[sym].greeks = greeksData;
					this._emitChainUpdate(sym);
				}
			};
			rtFeed.on('greeks', this._listeners.greeks);
		}
	}

	/**
	 * Emit merged data for a symbol whenever any feed updates.
	 * Default fields from tick: Symbol, Symbol_ID, Timestamp, LTP, LTQ, ATP,
	 * Volume, Prev_Close, Price_Change, Price_Change_Percentage, OI,
	 * Prev_Open_Int_Close, OI_Change, OI_Change_Percentage
	 * When bidAsk=true: also include Bid, Bid_Qty, Ask, Ask_Qty from tick
	 * When greek=true: merge greeks data
	 */
	_emitChainUpdate(sym) {
		const entry = this.chain[sym];
		if (!entry.tick) return;

		let merged = {
			Symbol: entry.tick.Symbol,
			Symbol_ID: entry.tick.Symbol_ID,
			Timestamp: entry.tick.Timestamp,
			LTP: entry.tick.LTP,
			LTQ: entry.tick.LTQ,
			ATP: entry.tick.ATP,
			Volume: entry.tick.Volume,
			Prev_Close: entry.tick.Prev_Close,
			Price_Change: entry.tick.Price_Change,
			Price_Change_Percentage: entry.tick.Price_Change_Percentage,
			OI: entry.tick.OI,
			Prev_Open_Int_Close: entry.tick.Prev_Open_Int_Close,
			OI_Change: entry.tick.OI_Change,
			OI_Change_Percentage: entry.tick.OI_Change_Percentage,
		};

		// Bidask fields come from tick data itself
		if (this.bidAsk) {
			merged.Bid = entry.tick.Bid;
			merged.Bid_Qty = entry.tick.Bid_Qty;
			merged.Ask = entry.tick.Ask;
			merged.Ask_Qty = entry.tick.Ask_Qty;
		}

		// Merge greeks if enabled and available
		if (this.greek && entry.greeks) {
			merged.IV = entry.greeks.IV;
			merged.Delta = entry.greeks.Delta;
			merged.Theta = entry.greeks.Theta;
			merged.Gamma = entry.greeks.Gamma;
			merged.Vega = entry.greeks.Vega;
			merged.Rho = entry.greeks.Rho;
		}

		rtFeed.emit('optionchain', merged);
	}

	/**
	 * Get the full current option chain snapshot organized by strike.
	 * Returns: { strike: { CE: {...}, PE: {...} }, ... }
	 */
	getChainSnapshot() {
		const snapshot = {};
		const expiryShort = this.expiry.slice(2);

		this.strikes.forEach((strike) => {
			const ceSymbol = `${this.symbol}${expiryShort}${strike}CE`;
			const peSymbol = `${this.symbol}${expiryShort}${strike}PE`;

			const ceEntry = this.chain[ceSymbol];
			const peEntry = this.chain[peSymbol];

			snapshot[strike] = {
				CE: ceEntry && ceEntry.tick ? this._mergeEntry(ceEntry) : null,
				PE: peEntry && peEntry.tick ? this._mergeEntry(peEntry) : null,
			};
		});
		return snapshot;
	}

	_mergeEntry(entry) {
		let merged = {
			Symbol: entry.tick.Symbol,
			Symbol_ID: entry.tick.Symbol_ID,
			Timestamp: entry.tick.Timestamp,
			LTP: entry.tick.LTP,
			LTQ: entry.tick.LTQ,
			ATP: entry.tick.ATP,
			Volume: entry.tick.Volume,
			Prev_Close: entry.tick.Prev_Close,
			Price_Change: entry.tick.Price_Change,
			Price_Change_Percentage: entry.tick.Price_Change_Percentage,
			OI: entry.tick.OI,
			Prev_Open_Int_Close: entry.tick.Prev_Open_Int_Close,
			OI_Change: entry.tick.OI_Change,
			OI_Change_Percentage: entry.tick.OI_Change_Percentage,
			Strike: entry.strike,
			OptionType: entry.type,
		};

		if (this.bidAsk) {
			merged.Bid = entry.tick.Bid;
			merged.Bid_Qty = entry.tick.Bid_Qty;
			merged.Ask = entry.tick.Ask;
			merged.Ask_Qty = entry.tick.Ask_Qty;
		}

		if (this.greek && entry.greeks) {
			merged.IV = entry.greeks.IV;
			merged.Delta = entry.greeks.Delta;
			merged.Theta = entry.greeks.Theta;
			merged.Gamma = entry.greeks.Gamma;
			merged.Vega = entry.greeks.Vega;
			merged.Rho = entry.greeks.Rho;
		}
		return merged;
	}

	/**
	 * Stop listening and clean up event listeners.
	 */
	stopListening() {
		if (this._listeners.tick) rtFeed.removeListener('tick', this._listeners.tick);
		if (this._listeners.greeks) rtFeed.removeListener('greeks', this._listeners.greeks);
		this._listeners = {};
	}
}

/**
 * Fetch ATM strike and strike step from TrueData API.
 */
async function getATMStrike(username, password, symbol, expiry) {
	const url = 'https://api.truedata.in/getATMStrike';
	const params = { user: username, password: password, symbol: symbol, expiry: expiry };

	const response = await axios.get(url, { params });

	if (response.data.status !== 'Success') {
		throw new Error(`getATMStrike failed: ${JSON.stringify(response.data)}`);
	}

	const { strike, strikestep } = response.data.Records;
	return { atm: strike, strikeStep: strikestep };
}

module.exports = { OptionChain, getATMStrike };
